// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max - 1);

        // The contract holds exactly `amount`; we ask it to send `amount + 1`.
        // A correct (reverting) send cannot fulfill this; a silently-failing one can.
        vm.deal(address(c), amount);
        uint256 receiverBefore = receiver.balance;

        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, amount + 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful sendTo must have moved exactly amount+1 wei
        // to receiver; a sendTo that could not move the funds must not report success.
        assertTrue(!ok || receiver.balance == receiverBefore + amount + 1);
    }
}

