pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address receiver, uint256 amount) public {
        vm.assume(actor != address(this)); // actor must not be the owner
        vm.assume(uint256(uint160(receiver)) != 0); // receiver not address(0)
        amount = bound(amount, 1, 1e18);

        vm.deal(address(c), 10e18);
        uint256 before = address(c).balance;

        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        // Rule: reverting calls never move c's funds; successful calls move exactly amount.
        assertTrue(ok ? address(c).balance == before - amount : address(c).balance == before);
    }
}

